INSERT INTO changelog (title, body, created_at) VALUES ('Продажі клієнта — компактно і з графіком', 'Клієнт → Продажі: стан CRM одним рядком (з «Оновити зараз»), 4 головні цифри (ліди, продажі, сума, лід → продаж) і смужка з середнім чеком, оплатами, швидкістю реакції і лідами без контакту. Новий графік: стовпчики — ліди, лінія — продажі (30 днів по днях, 90 — по тижнях, рік — по місяцях). Реклама → продажі, Джерела, Менеджери, Де зараз ліди, Причини відмов, Точка нуль, Події з CRM і Підключення — плитки, деталі у віконці.', datetime('now'));
